import hmac
import hashlib
import base64
import json
import time
import os
from http.server import HTTPServer, BaseHTTPRequestHandler
import urllib.parse
import secrets

# Configuration
JWT_SECRET = os.environ.get('JWT_SECRET', secrets.token_hex(32))
ENFORCED_ALGORITHM = 'HS256'  # Server-side enforced algorithm
TOKEN_EXPIRY = 3600

def base64url_decode(data):
    """RFC 7515 compliant base64url decoding"""
    padding = 4 - len(data) % 4
    if padding != 4:
        data += '=' * padding
    return base64.urlsafe_b64decode(data.encode('utf-8'))

def base64url_encode(data):
    """RFC 7515 compliant base64url encoding"""
    if isinstance(data, str):
        data = data.encode('utf-8')
    return base64.urlsafe_b64encode(data).rstrip(b'=').decode('utf-8')

def get_hash_function(algorithm):
    """Map JWT algorithm name to hashlib function"""
    mapping = {
        'HS256': hashlib.sha256,
        'HS384': hashlib.sha384,
        'HS512': hashlib.sha512
    }
    return mapping.get(algorithm)

def compute_signature(signing_input, algorithm, secret):
    """Compute HMAC signature for JWT"""
    hash_func = get_hash_function(algorithm)
    if hash_func is None:
        return None
    return hmac.new(secret.encode('utf-8'), signing_input.encode('utf-8'), hash_func).digest()

def validate_token_structure(token):
    """Validate JWT has correct structure (3 parts)"""
    parts = token.split('.')
    if len(parts) != 3:
        return None, None, None
    return parts[0], parts[1], parts[2]

def decode_token_header(header_b64):
    """Decode and parse JWT header"""
    try:
        header_json = base64url_decode(header_b64)
        header = json.loads(header_json)
        return header
    except (json.JSONDecodeError, Exception):
        return None

def decode_token_payload(payload_b64):
    """Decode and parse JWT payload"""
    try:
        payload_json = base64url_decode(payload_b64)
        payload = json.loads(payload_json)
        return payload
    except (json.JSONDecodeError, Exception):
        return None

def verify_token_signature(header_b64, payload_b64, signature_b64, algorithm, secret):
    """Verify the JWT signature using the server-enforced algorithm"""
    signing_input = f"{header_b64}.{payload_b64}"
    expected_sig = compute_signature(signing_input, algorithm, secret)
    if expected_sig is None:
        return False
    try:
        provided_sig = base64url_decode(signature_b64)
    except Exception:
        return False
    return hmac.compare_digest(expected_sig, provided_sig)

def validate_token_claims(payload):
    """Validate standard JWT claims (exp, iat, nbf)"""
    current_time = int(time.time())

    if 'exp' in payload:
        if current_time > payload['exp']:
            return False, 'Token expired'

    if 'nbf' in payload:
        if current_time < payload['nbf']:
            return False, 'Token not yet valid'

    if 'iat' in payload:
        if payload['iat'] > current_time + 60:  # 60s clock skew
            return False, 'Token issued in the future'

    return True, None

def authenticate_request(token, secret):
    """Main authentication function - validates JWT token

    Security: Validates structure, enforces server-side algorithm (ignores
    token header alg claim), verifies signature, and validates claims.
    Uses constant-time comparison for signature verification.
    """
    # Step 1: Validate structure
    header_b64, payload_b64, signature_b64 = validate_token_structure(token)
    if header_b64 is None:
        return None, 'Invalid token structure'

    # Step 2: Decode header (for logging/audit only, not for algorithm selection)
    header = decode_token_header(header_b64)
    if header is None:
        return None, 'Invalid token header'

    # Step 3: Enforce server-side algorithm - IGNORE token's declared algorithm
    # This prevents algorithm confusion attacks (e.g., alg:none, RS256->HS256)
    server_algorithm = ENFORCED_ALGORITHM

    # Step 4: Verify signature using SERVER's algorithm, not token's
    if not verify_token_signature(header_b64, payload_b64, signature_b64, server_algorithm, secret):
        return None, 'Invalid signature'

    # Step 5: Decode and validate payload claims
    payload = decode_token_payload(payload_b64)
    if payload is None:
        return None, 'Invalid token payload'

    claims_valid, error = validate_token_claims(payload)
    if not claims_valid:
        return None, error

    return payload, None

def get_user_permissions(payload):
    """Extract user permissions from validated token payload"""
    return payload.get('permissions', [])

def authorize_action(payload, required_permission):
    """Check if user has required permission"""
    permissions = get_user_permissions(payload)
    return required_permission in permissions

class SecureAPIHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        # Extract token from Authorization header
        auth_header = self.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            self.send_error(401, 'Missing or invalid Authorization header')
            return

        token = auth_header[7:]  # Remove 'Bearer ' prefix

        # Authenticate
        payload, error = authenticate_request(token, JWT_SECRET)
        if payload is None:
            self.send_error(401, f'Authentication failed: {error}')
            return

        # Parse path and authorize
        parsed_path = urllib.parse.urlparse(self.path)
        path = parsed_path.path

        if path == '/api/admin/users':
            if not authorize_action(payload, 'admin:read'):
                self.send_error(403, 'Insufficient permissions')
                return
            self.send_response(200)
            self.send_header('Content-Type', 'application/json')
            self.end_headers()
            self.wfile.write(json.dumps({'users': ['alice', 'bob']}).encode())

        elif path == '/api/admin/secrets':
            if not authorize_action(payload, 'admin:secrets'):
                self.send_error(403, 'Insufficient permissions')
                return
            self.send_response(200)
            self.send_header('Content-Type', 'application/json')
            self.end_headers()
            # Sensitive data that requires admin:secrets permission
            self.wfile.write(json.dumps({'secret_key': 'internal-api-key-12345'}).encode())

        elif path == '/api/profile':
            self.send_response(200)
            self.send_header('Content-Type', 'application/json')
            self.end_headers()
            self.wfile.write(json.dumps({
                'user': payload.get('sub', 'unknown'),
                'permissions': get_user_permissions(payload)
            }).encode())

        else:
            self.send_error(404, 'Not found')

if __name__ == '__main__':
    server = HTTPServer(('127.0.0.1', 8443), SecureAPIHandler)
    print('Starting secure API server on port 8443')
    server.serve_forever()
